"""063 public reporting projection. Inputs are generated safe summaries only."""
import json,html
from project_portal import shell,ASSETS
E=lambda x:html.escape(str(x),quote=True)
def page():
 d=json.loads((ASSETS/'data-report.json').read_text());s=d['summary'];rows=[]
 for label,key,note in [('项目题录','catalog_entries','目录规模，不等于完成研究'),('金奖研究版','published_research','98案均已建立版本化档案'),('定向补证报告','deepening_reports','后续深化已保存的项目报告'),('方法档案','methods','已形成独立内容校准基线')]:rows.append('<article><span>'+label+'</span><b>'+str(s[key])+'</b><small>'+note+'</small></article>')
 body='<header class="dr-heading"><div class="pp-kicker">项目库 × 方法库 / 数据汇报</div><h1>数据工作与质量总览</h1><p>看清已经建立的能力、现有数据，以及离高质量交付还差什么。</p><div class="dr-stamp">数据快照：'+E(d['generated_at'].replace('T',' ')[:19])+'（首尔时间）<button id="print-report">打印汇报</button></div></header><nav class="dr-sections" aria-label="汇报章节"><a href="#work">做了什么</a><a href="#data">数据现状</a><a href="#quality">质量情况</a><a href="#details">逐项清单</a><a href="#next">下一步</a></nav><div class="dr-kpis">'+''.join(rows)+'</div>'
 body+='<section class="dr-section" id="work"><div class="pp-kicker">01 / 工作进展</div><h2>从资料整理，走到可读、可查、可调用</h2><div class="dr-work">'+''.join('<article><div><h3>'+E(c['title'])+'</h3><span>'+E(c['status'])+'</span></div><p>'+E(c['detail'])+'</p></article>'for c in d['capabilities'])+'</div></section>'
 body+='<section class="dr-section" id="data"><div class="pp-kicker">02 / 当前数据</div><h2>规模和处理阶段，分别呈现</h2><div class="dr-data-grid"><article><h3>项目库</h3><dl>'+''.join('<div><dt>'+label+'</dt><dd>'+str(n)+'</dd></div>'for label,n in [('项目题录',s['catalog_entries']),('金奖项目',s['gold_projects']),('已建立研究版',s['published_research']),('本轮基础检索报告',s['basic_coverage']),('后续定向补证报告',s['deepening_reports'])])+'</dl></article><article><h3>98案结构化数据</h3><dl>'+''.join('<div><dt>'+label+'</dt><dd>'+str(n)+'</dd></div>'for label,n in [('结构化记录',s['fact_records']),('已知值字段',s['known_cells']),('项目来源登记条目',s['project_source_entries']),('本轮增量已入档项目',s['incremental_projects']),('本轮增量已入档字段',s['incremental_fields'])])+'</dl></article><article><h3>方法与调用</h3><dl>'+''.join('<div><dt>'+label+'</dt><dd>'+str(n)+'</dd></div>'for label,n in [('方法档案',s['methods']),('独立校准基线',s['method_calibrated']),('统一入口工具',10),('只读工具',9),('独立计划保存工具',1)])+'</dl></article></div><p class="dr-note">'+E(d['scope'])+' 来源按项目登记，未跨项目去重；已知值不等于独立验证，检索报告也不等于内容审核入档。</p></section>'
 body+='<section class="dr-section" id="quality"><div class="pp-kicker">03 / 数据质量</div><h2>基础覆盖已经完成，质量目标仍在推进</h2><p class="dr-quality-note">'+E(d['quality_notice'])+'</p><div class="dr-quality-grid"><article><h3>98案内容评估状态</h3>'
 for label,n in d['project_quality_counts'].items():body+='<div class="dr-bar-row"><span>'+E(label)+'</span><b>'+str(n)+' 案</b><progress max="98" value="'+str(n)+'" aria-label="'+E(label)+'">'+str(n)+'</progress></div>'
 body+='<p class="dr-note">当前版本匹配的独立Agent试评分范围：'+E(d['project_calibrated_range'][0])+'–'+E(d['project_calibrated_range'][1])+' / 100，仅覆盖部分项目，不是98案平均分。</p>'
 body+='<p class="dr-note">旧评估汇总生成于 '+E(d['assessment_snapshot_at'][:10])+'；本页逐案对照当前研究版本和指纹。不匹配的旧分数隐藏，等待复评，未评不算0。</p></article><article><h3>64方法内容基线</h3><p class="dr-score-range">'+E(d['method_baseline_range'][0])+'<span>—</span>'+E(d['method_baseline_range'][1])+'<small>独立Agent内容校准 · 满分100</small></p><p>64份基线均有校准记录，尚无80分验收通过结论。主要短板是原典逐主张支持、完整实践产物和实际应用证据。</p><h4>增补组合版本另行看</h4><div class="dr-upgrades">'+''.join('<div><a href="/inno/methods/methods/'+E(x['id'])+'.html">'+E(x['id'])+'</a><b>'+E(x['score'])+'</b></div>'for x in d['method_upgrades'])+'</div><p class="dr-note">以上是教学增补组合的独立Agent试评，未覆盖冻结基线，不代表真实工程或专家认证。</p></article></div></section>'
 body+='<section class="dr-section" id="details"><div class="pp-kicker">04 / 逐项明细</div><h2>查看每个项目与方法的状态</h2><div class="dr-tabs" role="group" aria-label="数据清单"><button data-table="projects" aria-pressed="true">98个金奖项目</button><button data-table="methods" aria-pressed="false">64个创新方法</button></div><label class="dr-search">检索清单<input id="report-search" type="search" placeholder="搜索名称、ID、状态或缺口"></label><p id="detail-count" role="status" aria-live="polite"></p>'
 body+='<div class="dr-table-panel" data-panel="projects"><div class="dr-table-scroll"><table><thead><tr><th>项目</th><th>当前版本</th><th>基础 / 深化</th><th>内容分数</th><th>评估状态与缺口</th></tr></thead><tbody>'
 for x in d['projects']:
  body+='<tr><td><small>'+E(x['id'])+'</small><a href="/inno/dossier/?project='+E(x['id'])+'">'+E(x['name'])+'</a></td><td>'+E(x['revision']or'未发布')+'</td><td>基础检索已保存<br>'+('定向报告已保存'if x['deepening']else'待定向补证')+'</td><td>'+E(x['score']if x['score']is not None else'未评 / 待复评')+'</td><td><b>'+E(x['quality_status'])+'</b><p>'+E('；'.join(x['gaps'][:2]))+'</p></td></tr>'
 body+='</tbody></table></div></div><div class="dr-table-panel" data-panel="methods" hidden><div class="dr-table-scroll"><table><thead><tr><th>方法</th><th>版本 / 分类</th><th>基线内容分数</th><th>状态与下一步</th></tr></thead><tbody>'
 for x in d['methods']:body+='<tr><td><small>'+E(x['id'])+'</small><a href="/inno/methods/methods/'+E(x['id'])+'.html">'+E(x['name'])+'</a></td><td>'+E(x['version'])+'<br>'+E(x['category'])+'</td><td>'+E(x['score']if x['score']is not None else'未评')+'</td><td><b>'+E(x['quality_status'])+'</b><p>'+E('；'.join(x['gaps']))+'</p></td></tr>'
 body+='</tbody></table></div></div><div class="pp-pagination"><button id="detail-prev">← 上一页</button><span id="detail-page"></span><button id="detail-next">下一页 →</button></div></section>'
 body+='<section class="dr-section" id="next"><div class="pp-kicker">05 / 后续重点</div><h2>接下来补什么，怎样算完成</h2><ol class="dr-next">'+''.join('<li>'+E(x)+'</li>'for x in d['next_actions'])+'</ol><p><a href="/inno/projects/">探索项目库 →</a>　<a href="/inno/methods/">进入方法库 →</a>　<a href="/inno/mcp/">统一MCP接入 →</a></p><p class="dr-note">本页为按实际记录生成的汇报快照，并非实时监控。数据刷新不自动更新原始评估或提升分数。</p></section>'
 return shell('数据工作与质量汇报',body,'<link rel="stylesheet" href="/inno/portal/data-report.css"><script src="/inno/portal/data-report.js"></script>',active='report')
